def build_prompt(question, context=None):
    system = "你是一名严谨的技术助手，回答要简洁、准确、分点。"
    user = f"请回答以下问题：\n{question}\n"
    if context:
        user += f"\n参考材料：\n{context}\n"
    user += "\n请在 3 句话以内作答。"
    # 用分隔符区分指令与数据，避免被输入内容劫持
    return [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]

if __name__ == "__main__":
    msgs = build_prompt("什么是注意力机制？")
    for m in msgs:
        print(f"[{m['role']}] {m['content']}")

