import numpy as np

def cosine(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

def retrieve(question, docs, vecs, top_k):
    q = question
    scored = sorted(zip(vecs, docs), key=lambda x: cosine(q, x[0]), reverse=True)
    return [d for _, d in scored[:top_k]]

