from fastmcp import FastMCP

mcp = FastMCP("demo")

# 定义一个可被模型调用的工具
@mcp.tool()
def search_notes(keyword: str) -> list:
    """按关键词搜索笔记，返回匹配结果。"""
    notes = {
        "attention": ["注意力机制笔记"],
        "rag": ["RAG 检索增强生成笔记"],
    }
    return notes.get(keyword.lower(), [])

# 定义可读取的资源
@mcp.resource("notes://rag")
def rag_note() -> str:
    return "RAG 先检索再生成，减少幻觉。"

if __name__ == "__main__":
    # 运行 MCP 服务器（通常用 stdio 或 http 传输）
    mcp.run()

